def vincular_grupos_existentes(apps, schema_editor):
    Plano = apps.get_model('replicacao', 'PlanoReplicacao')
    Empresa = apps.get_model('empresas', 'Empresa')
    Destino = apps.get_model('replicacao', 'DestinoReplicacao')
    for plano in Plano.objects.select_related('matriz').all():
        grupo = plano.matriz.grupo
        if not grupo.strip():
            continue
        participantes = {plano.matriz_id, *Destino.objects.filter(plano=plano).values_list('empresa_id', flat=True)}
        empresas = Empresa.objects.filter(grupo__iexact=grupo, ativa=True)
        if plano.marca_id:
            empresas = empresas.filter(ambientes_white_label__pk=plano.marca_id)
        if len(participantes) >= 2 and set(empresas.values_list('pk', flat=True)) == participantes:
            Plano.objects.filter(pk=plano.pk).update(grupo=grupo)


